import clsx from 'clsx';
import { memo, useEffect, useState } from 'react';

export type ToggleSwitchProps = {
  onToggle?: (on: boolean) => void | boolean;
  on?: boolean;
};

export const ToggleSwitch = memo(function ToggleSwitch({ on = false, onToggle }: ToggleSwitchProps) {
  const [isOn, setIsOn] = useState(on);
  const handleClick = () => {
    setIsOn((prev) => {
      const result = !prev;
      const shouldToggle = onToggle?.(result);
      if (shouldToggle === false) {
        return prev;
      }
      return result;
    });
  };
  useEffect(() => {
    setIsOn(on);
  }, [on]);
  return (
    <button type="button" className={clsx('toggle-btn', { on: isOn })} onClick={handleClick}>
      <span className="toggle">Toggle</span>
    </button>
  );
});
